fn main() {
    // Let rustc's autogenerated .def export the #[no_mangle] Rust functions.
    // A second /DEF: file replaces that export list and creates a tiny
    // forwarding-only DLL, so do NOT pass /DEF:msvcp140.def here.
    println!("cargo:rustc-cdylib-link-arg=/NODEFAULTLIB");
    println!("cargo:rustc-cdylib-link-arg=/ENTRY:DllMain");
    println!("cargo:rustc-cdylib-link-arg=/BASE:0x7e001c000000");

    // Forward the three existing MSVCP140 helpers while preserving every
    // Rust-exported function in the linker-generated export definition.
    for export in [
        "?uncaught_exceptions@std@@YAHXZ=ucrtbase.__uncaught_exceptions",
        "_Query_perf_counter=kernel32.VeilQueryPerfCounter",
        "_Query_perf_frequency=kernel32.VeilQueryPerfFrequency",
    ] {
        println!("cargo:rustc-cdylib-link-arg=/EXPORT:{export}");
    }
}
